1	// QEMU TCG plugin: drains architectural state and exits when the guest
2	// executes the ROI enter marker `slti x0, x0, 0x5A0` (a HINT NOP). Shares
3	// hybrid/insn_match.h and hybrid/state_abi.h with the vsim side.
4	
5	#include "hybrid/handoff_site.h"
6	#include "hybrid/insn_match.h"
7	#include "hybrid/reg_names.h"
8	#include "hybrid/state_abi.h"
9	#include "hybrid/v_drain_policy.h"
10	
11	#include <qemu-plugin.h>
12	
13	#include <glib.h>
14	
15	#include <fcntl.h>
16	#include <inttypes.h>
17	#include <stddef.h>
18	#include <stdint.h>
19	#include <stdio.h>
20	#include <stdlib.h>
21	#include <string.h>
22	#include <unistd.h>
23	#include <limits.h>
24	
25	QEMU_PLUGIN_EXPORT int qemu_plugin_version = QEMU_PLUGIN_VERSION;
26	
27	typedef struct {
28	    struct qemu_plugin_register *gpr[32];
29	    struct qemu_plugin_register *fpr[32];
30	    struct qemu_plugin_register *fcsr;  // L20: frm[7:5] | fflags[4:0]
31	    struct qemu_plugin_register *pc;
32	    struct qemu_plugin_register *priv;  // L6: gdbstub virtual feature
33	
34	    // M-mode CSRs as exposed by QEMU's gdbstub csr feature.
35	    struct qemu_plugin_register *mstatus;
36	    struct qemu_plugin_register *mepc;
37	    struct qemu_plugin_register *mtvec;
38	    struct qemu_plugin_register *mcause;
39	    struct qemu_plugin_register *mtval;
40	    struct qemu_plugin_register *mscratch;
41	    struct qemu_plugin_register *medeleg;
42	    struct qemu_plugin_register *mideleg;
43	    struct qemu_plugin_register *mip;
44	    struct qemu_plugin_register *mie;
45	    struct qemu_plugin_register *mcycle;
46	    struct qemu_plugin_register *minstret;
47	    struct qemu_plugin_register *satp;
48	
49	    // Andes custom machine setup CSRs (crt0 writes these at boot). mcache_ctl
50	    // enables the L1 caches; without transporting it the cycle engine resumes
51	    // with caches off. Absent on non-Andes stubs -> NULL handle -> drains 0.
52	    struct qemu_plugin_register *mcache_ctl;
53	    struct qemu_plugin_register *mmisc_ctl;
54	
55	    struct qemu_plugin_register *pmpcfg[HYBRID_PMP_CFG_NUM];
56	    struct qemu_plugin_register *pmpaddr[HYBRID_PMP_ADDR_NUM];
57	
58	    struct qemu_plugin_register *vstart;
59	    struct qemu_plugin_register *vxsat;
60	    struct qemu_plugin_register *vxrm;
61	    struct qemu_plugin_register *vcsr;
62	    struct qemu_plugin_register *vtype;
63	    struct qemu_plugin_register *vl;
64	    struct qemu_plugin_register *vlenb;
65	    struct qemu_plugin_register *vreg[32];
66	} VcpuRegs;
67	
68	static struct qemu_plugin_scoreboard *vcpu_state;
69	static char *outfile_path;
70	
71	// PC-trigger mode: when enter_pc_arg is non-zero (set via plugin arg
72	// `enter_pc=0x...`), the CSR-insn matcher is bypassed entirely and the
73	// drain callback is registered only for instructions whose vaddr equals
74	// enter_pc_arg. The kind reported on the drain is HYBRID_HANDOFF_ENTER
75	// (entry into vsim), matching marker-mode enter-marker semantics.
76	static uint64_t enter_pc_arg;
77	static int pc_mode;
78	
79	// Oracle exit-drain mode (verify_oracle F1): when exit_marker_mode or
80	// exit_pc_mode is set (plugin args `exit_marker=1` / `exit_pc=0x...`), a
81	// pure-QEMU run produces the differential verifier's reference state. Every
82	// insn gets an exec callback: the tick ARMS on the
83	// ROI exit boundary (EXIT marker match, or vaddr == exit_pc) and DRAINS on
84	// the next callback. Exec callbacks fire before their insn executes, so the
85	// armed drain captures "after the boundary insn retired" -- exactly vsim's
86	// exit-drain record (DPC = next insn to execute) -- and reports that next
87	// insn's vaddr as pc, correct even when the boundary insn branches.
88	// Exclusive with the other trigger modes: the oracle run never hands off.
89	//
90	// drain_pc=0x... (optional modifier): drain at the first post-arm tick whose
91	// vaddr equals drain_pc, instead of the very next tick. The differential
92	// harness passes vsim's actual drained pc here: vsim's DMI halt lands a
93	// variable 0-3 insns past the trigger (the core keeps retiring while the
94	// haltreq propagates), and the two states only compare equal when both
95	// sides sample the SAME architectural point. If vsim's pc is never reached
96	// (a real control-flow divergence), the oracle never drains and QEMU runs
97	// to completion -- the caller sees exit != 200.
98	static uint64_t exit_pc_arg;
99	static int      exit_pc_mode;
100	static int      exit_marker_mode;
101	static uint64_t drain_pc_arg;
102	static int      drain_pc_set;
103	static volatile int oracle_armed;
104	
105	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
106	{
107	    for (guint i = 0; i < regs->len; i++) {
108	        qemu_plugin_reg_descriptor *rd =
109	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
110	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
111	            return rd->handle;
112	        }
113	    }
114	    return NULL;
115	}
116	
117	// Lazily resolves register handles. The plugin's vcpu_init runs before
118	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
119	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
120	// regs at that moment. By the time the entry trigger fires, all dynamic
121	// features are registered and a fresh call returns the full list.
122	static void resolve_handles(VcpuRegs *v)
123	{
124	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
125	    for (int i = 0; i < 32; i++) {
126	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
127	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
128	    }
129	    v->fcsr = find_reg(regs, "fcsr");
130	    v->pc = find_reg(regs, "pc");
131	    v->priv = find_reg(regs, "priv");
132	
133	    v->mstatus  = find_reg(regs, "mstatus");
134	    v->mepc     = find_reg(regs, "mepc");
135	    v->mtvec    = find_reg(regs, "mtvec");
136	    v->mcause   = find_reg(regs, "mcause");
137	    v->mtval    = find_reg(regs, "mtval");
138	    v->mscratch = find_reg(regs, "mscratch");
139	    v->medeleg  = find_reg(regs, "medeleg");
140	    v->mideleg  = find_reg(regs, "mideleg");
141	    v->mip      = find_reg(regs, "mip");
142	    v->mie      = find_reg(regs, "mie");
143	    v->mcycle   = find_reg(regs, "mcycle");
144	    v->minstret = find_reg(regs, "minstret");
145	    v->satp     = find_reg(regs, "satp");
146	
147	    v->mcache_ctl = find_reg(regs, "mcache_ctl");
148	    v->mmisc_ctl  = find_reg(regs, "mmisc_ctl");
149	
150	    char buf[16];
151	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
152	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
153	        v->pmpcfg[i] = find_reg(regs, buf);
154	    }
155	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
156	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
157	        v->pmpaddr[i] = find_reg(regs, buf);
158	    }
159	
160	    v->vstart = find_reg(regs, "vstart");
161	    v->vxsat  = find_reg(regs, "vxsat");
162	    v->vxrm   = find_reg(regs, "vxrm");
163	    v->vcsr   = find_reg(regs, "vcsr");
164	    v->vtype  = find_reg(regs, "vtype");
165	    v->vl     = find_reg(regs, "vl");
166	    v->vlenb  = find_reg(regs, "vlenb");
167	    for (int i = 0; i < 32; i++) {
168	        g_snprintf(buf, sizeof(buf), "v%d", i);
169	        v->vreg[i] = find_reg(regs, buf);
170	    }
171	}
172	
173	static uint64_t read_reg64(struct qemu_plugin_register *h)
174	{
175	    if (!h) return 0;
176	    g_autoptr(GByteArray) buf = g_byte_array_new();
177	    int sz = qemu_plugin_read_register(h, buf);
178	    if (sz <= 0) return 0;
179	    uint64_t v = 0;
180	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
181	    return v;
182	}
183	
184	// Reads up to `dst_max` bytes from a register handle. Returns the byte
185	// count written (0 on failure or NULL handle). Used for vector regs whose
186	// width = vlenb bytes.
187	static size_t read_reg_bytes(struct qemu_plugin_register *h,
188	                             uint8_t *dst, size_t dst_max)
189	{
190	    if (!h || dst_max == 0) return 0;
191	    g_autoptr(GByteArray) buf = g_byte_array_new();
192	    int sz = qemu_plugin_read_register(h, buf);
193	    if (sz <= 0) return 0;
194	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
195	    memcpy(dst, buf->data, n);
196	    return n;
197	}
198	
199	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
200	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
201	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
202	// collide even under aggressive PID reuse (B13). The tmp lives in the
203	// same directory as `path` so the rename is intra-filesystem.
204	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
205	{
206	    char tmp[PATH_MAX];
207	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
208	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
209	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
210	        return -1;
211	    }
212	    int fd = g_mkstemp(tmp);
213	    if (fd < 0) {
214	        perror("hybrid_handoff: g_mkstemp");
215	        return -1;
216	    }
217	    // g_mkstemp creates the file 0600; no further chmod needed.
218	    ssize_t want = (ssize_t) sizeof(*s);
219	    ssize_t got = write(fd, s, sizeof(*s));
220	    if (got != want) {
221	        perror("hybrid_handoff: write");
222	        close(fd);
223	        unlink(tmp);
224	        return -1;
225	    }
226	    fsync(fd);
227	    close(fd);
228	    if (rename(tmp, path) != 0) {
229	        perror("hybrid_handoff: rename");
230	        unlink(tmp);
231	        return -1;
232	    }
233	    return 0;
234	}
235	
236	// Drain CPU state into `*s`. pc is computed by the caller (from a
237	// HandoffSite for trigger paths). If minstret_override is non-zero, it
238	// replaces QEMU's PMU minstret.
239	static void drain_state_into(unsigned int vcpu_idx, uint64_t pc,
240	                             uint64_t minstret_override,
241	                             struct hybrid_state_v1 *sp)
242	{
243	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
244	    resolve_handles(v);
245	    memset(sp, 0, sizeof(*sp));
246	    struct hybrid_state_v1 s = {0};
247	    s.magic   = HYBRID_STATE_MAGIC;
248	    s.version = HYBRID_STATE_VERSION;
249	    s.flags   = HYBRID_FLAG_RV64;
250	    s.hart_id = vcpu_idx;
251	    // L6: real privilege at the boundary; M-mode fallback only when the
252	    // stub doesn't advertise the gdbstub virtual feature (a missing handle
253	    // reads as 0 = U, which would silently demote the hart).
254	    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
255	    s.pc      = pc;
256	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
257	
258	    // Floating-point: only set FP flag if at least one handle was bound,
259	    // i.e. QEMU advertised the FPU feature (D extension).
260	    int has_fp = 0;
261	    for (int i = 0; i < 32; i++) {
262	        s.fpr[i] = read_reg64(v->fpr[i]);
263	        if (v->fpr[i]) has_fp = 1;
264	    }
265	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
266	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
267	
268	    s.mstatus  = read_reg64(v->mstatus);
269	    s.mepc     = read_reg64(v->mepc);
270	    s.mtvec    = read_reg64(v->mtvec);
271	    s.mcause   = read_reg64(v->mcause);
272	    s.mtval    = read_reg64(v->mtval);
273	    s.mscratch = read_reg64(v->mscratch);
274	    s.medeleg  = read_reg64(v->medeleg);
275	    s.mideleg  = read_reg64(v->mideleg);
276	    s.mip      = read_reg64(v->mip);
277	    s.mie      = read_reg64(v->mie);
278	    s.mcycle   = read_reg64(v->mcycle);
279	    s.minstret = minstret_override ? minstret_override
280	                                   : read_reg64(v->minstret);
281	    s.satp     = read_reg64(v->satp);
282	
283	    // Andes cache fix: carry crt0's cache-enable so the cycle engine resumes
284	    // with caches on (NULL handle on a non-Andes stub reads back as 0).
285	    s.mcache_ctl = read_reg64(v->mcache_ctl);
286	    s.mmisc_ctl  = read_reg64(v->mmisc_ctl);
287	
288	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
289	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
290	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
291	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
292	
293	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
294	    // bounds the per-register byte count copied into vreg[]. The policy
295	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
296	    // handle truthiness so we don't conflate "stub missing vlenb" with
297	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
298	    s.vstart = read_reg64(v->vstart);
299	    s.vxsat  = read_reg64(v->vxsat);
300	    s.vxrm   = read_reg64(v->vxrm);
301	    s.vcsr   = read_reg64(v->vcsr);
302	    s.vtype  = read_reg64(v->vtype);
303	    s.vl     = read_reg64(v->vl);
304	    s.vlenb  = read_reg64(v->vlenb);
305	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
306	                       || v->vtype || v->vl);
307	    if (!has_other_v) {
308	        for (int i = 0; i < 32; i++)
309	            if (v->vreg[i]) { has_other_v = 1; break; }
310	    }
311	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
312	        v->vlenb != NULL, has_other_v, s.vlenb);
313	    if (vpol == HYBRID_V_DRAIN_ABORT) {
314	        if (v->vlenb == NULL)
315	            fprintf(stderr,
316	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
317	                    "vlenb; refusing to drain partial V state\n");
318	        else
319	            fprintf(stderr,
320	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
321	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
322	                    "truncate V registers\n",
323	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
324	                    8 * HYBRID_VLEN_BYTES_MAX);
325	        exit(2);
326	    }
327	    if (vpol == HYBRID_V_DRAIN_OK) {
328	        s.flags |= HYBRID_FLAG_V;
329	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
330	         * full live register fits the wire-format slot -- no clamp (L11). */
331	        for (int i = 0; i < 32; i++)
332	            (void) read_reg_bytes(v->vreg[i],
333	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
334	                                  (size_t) s.vlenb);
335	    }
336	
337	    *sp = s;
338	}
339	
340	// Drain CPU state to `path`. Does NOT call exit -- the caller decides
341	// exit(200).
342	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
343	                                uint64_t minstret_override, const char *path)
344	{
345	    struct hybrid_state_v1 s;
346	    drain_state_into(vcpu_idx, pc, minstret_override, &s);
347	    if (write_state_atomic(&s, path) != 0) {
348	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
349	        exit(2);
350	    }
351	    fprintf(stderr,
352	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 ")\n",
353	            path, s.pc);
354	}
355	
356	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
357	// as the vsim resume point, and exit 200.
358	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
359	{
360	    drain_state_to_file(vcpu_idx, resume_pc, 0, outfile_path);
361	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
362	    // Distinguishes drain from workload completion (0) so the orchestrator
363	    // can decide the next spawn.
364	    exit(200);
365	}
366	
367	// Marker sites. The marker is an architectural NOP, so the pre-execution
368	// state equals the post-retire state and the window resumes AFTER it
369	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
370	// the exec callback can lag the actual current insn when V instructions
371	// retire just before the trigger -- TCG defers PC writes for performance).
372	static void on_handoff(unsigned int vcpu_idx, void *udata)
373	{
374	    const HandoffSite *site = (const HandoffSite *) udata;
375	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
376	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
377	}
378	
379	// pc boundary sites. Exec callbacks fire BEFORE the insn
380	// executes, and the boundary insn is real user code (unlike a marker NOP):
381	// the drained state must resume AT the boundary so the insn executes inside
382	// the vsim window rather than on neither leg. (Skipping it corrupts the
383	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
384	// set and the first vector op of the window faults.)
385	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
386	{
387	    const HandoffSite *site = (const HandoffSite *) udata;
388	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
389	    handoff_drain(vcpu_idx, site->vaddr);
390	}
391	
392	// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
393	// When armed (the exit boundary's own tick ran), this tick fires before its
394	// insn executes, so a drain here records the post-retire state of the
395	// boundary insn with pc = the dynamically-next insn's vaddr.
396	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
397	{
398	    const HandoffSite *site = (const HandoffSite *) udata;
399	    if (oracle_armed
400	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
401	        handoff_drain(vcpu_idx, site->vaddr);
402	    }
403	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
404	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
405	        oracle_armed = 1;
406	    }
407	}
408	
409	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
410	{
411	    (void) id;
412	    size_t n = qemu_plugin_tb_n_insns(tb);
413	
414	    for (size_t i = 0; i < n; i++) {
415	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
416	
417	        // Oracle exit-drain mode: exclusive with every other mode (enforced
418	        // at install), so it owns the insn's registration outright. The site
419	        // carries the marker kind so the tick can arm on the EXIT marker.
420	        if (exit_marker_mode || exit_pc_mode) {
421	            HandoffSite *site = g_new0(HandoffSite, 1);
422	            site->kind  = HYBRID_HANDOFF_NONE;
423	            site->vaddr = qemu_plugin_insn_vaddr(insn);
424	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
425	            if (exit_marker_mode && site->size == 4) {
426	                uint32_t raw = 0;
427	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
428	                    hybrid_match_handoff_insn(raw, &site->kind);
429	            }
430	            qemu_plugin_register_vcpu_insn_exec_cb(
431	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
432	            continue;
433	        }
434	
435	        if (pc_mode) {
436	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
437	            // boundary (on_handoff_boundary), so the insn size is recorded
438	            // only for completeness.
439	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
440	            HandoffSite *site = g_new0(HandoffSite, 1);
441	            site->kind  = HYBRID_HANDOFF_ENTER;
442	            site->vaddr = qemu_plugin_insn_vaddr(insn);
443	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
444	            qemu_plugin_register_vcpu_insn_exec_cb(
445	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
446	            continue;
447	        }
448	
449	        // Marker-trigger mode (default).
450	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
451	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
452	        // exact, not an approximation.
453	        size_t sz = qemu_plugin_insn_size(insn);
454	        if (sz != 4) continue;
455	        uint32_t raw = 0;
456	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
457	            continue;
458	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
459	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
460	        HandoffSite *site = g_new0(HandoffSite, 1);
461	        site->kind  = kind;
462	        site->vaddr = qemu_plugin_insn_vaddr(insn);
463	        site->size  = (uint32_t) sz;
464	        qemu_plugin_register_vcpu_insn_exec_cb(
465	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
466	    }
467	}
468	
469	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
470	                                           const qemu_info_t *info,
471	                                           int argc, char **argv)
472	{
473	    (void) info;
474	    for (int i = 0; i < argc; i++) {
475	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
476	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
477	            outfile_path = g_strdup(tok[1]);
478	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
479	            char *endp = NULL;
480	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
481	            if (!endp || *endp != '\0') {
482	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
483	                        tok[1]);
484	                return -1;
485	            }
486	            enter_pc_arg = (uint64_t) v;
487	            pc_mode = 1;
488	        } else if (g_strcmp0(tok[0], "exit_pc") == 0 && tok[1]) {
489	            char *endp = NULL;
490	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
491	            if (!endp || *endp != '\0') {
492	                fprintf(stderr, "hybrid_handoff: invalid exit_pc=%s\n",
493	                        tok[1]);
494	                return -1;
495	            }
496	            exit_pc_arg = (uint64_t) v;
497	            exit_pc_mode = 1;
498	        } else if (g_strcmp0(tok[0], "exit_marker") == 0 && tok[1]) {
499	            char *endp = NULL;
500	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
501	            if (!endp || *endp != '\0') {
502	                fprintf(stderr, "hybrid_handoff: invalid exit_marker=%s\n",
503	                        tok[1]);
504	                return -1;
505	            }
506	            exit_marker_mode = (v != 0);
507	        } else if (g_strcmp0(tok[0], "drain_pc") == 0 && tok[1]) {
508	            char *endp = NULL;
509	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
510	            if (!endp || *endp != '\0') {
511	                fprintf(stderr, "hybrid_handoff: invalid drain_pc=%s\n",
512	                        tok[1]);
513	                return -1;
514	            }
515	            drain_pc_arg = (uint64_t) v;
516	            drain_pc_set = 1;
517	        } else {
518	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
519	            return -1;
520	        }
521	    }
522	    if (!outfile_path) {
523	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
524	        return -1;
525	    }
526	    if (pc_mode) {
527	        fprintf(stderr,
528	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
529	                enter_pc_arg);
530	    }
531	    if (exit_marker_mode || exit_pc_mode) {
532	        if ((exit_marker_mode && exit_pc_mode) || pc_mode) {
533	            fputs("hybrid_handoff: oracle exit drain (exit_marker/exit_pc) "
534	                  "is exclusive with the other trigger modes\n", stderr);
535	            return -1;
536	        }
537	        if (exit_pc_mode) {
538	            fprintf(stderr,
539	                    "hybrid_handoff: oracle exit-drain mode exit_pc=0x%"
540	                    PRIx64 "\n", exit_pc_arg);
541	        } else {
542	            fputs("hybrid_handoff: oracle exit-drain mode (exit marker)\n",
543	                  stderr);
544	        }
545	        if (drain_pc_set) {
546	            fprintf(stderr, "hybrid_handoff: oracle drain_pc=0x%" PRIx64 "\n",
547	                    drain_pc_arg);
548	        }
549	    } else if (drain_pc_set) {
550	        fputs("hybrid_handoff: drain_pc requires oracle exit-drain mode "
551	              "(exit_marker/exit_pc)\n", stderr);
552	        return -1;
553	    }
554	
555	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
556	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
557	    return 0;
558	}
