94	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
95	    // dropped and the stale QEMU1 value passes through into the drained state.
96	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
97	
98	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
99	    // restores them), so re-read them -- an in-ROI write must reach the drained
100	    // state instead of the stale QEMU1 passthrough value.
101	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
102	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
103	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
104	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
105	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
106	
107	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
108	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
109	
