57	  {  // identical states -> ok, full field count
58	    const hybrid_state_v1 a = base_state();
59	    const DiffReport r = diff_states(a, a);
60	    CHECK(r.ok());
61	    CHECK(r.compared == kFullCompared);
62	  }
