111	    hybrid_state_v1 ref = base_state();
112	    ref.flags = HYBRID_FLAG_RV64;
113	    hybrid_state_v1 got = ref;
114	    got.mscratch = 0xdead;
115	    const DiffReport hy = diff_states(ref, got);
116	    CHECK(!hy.ok());
117	    CHECK(hy.diffs.size() == 1);
118	    CHECK(hy.diffs[0].field == "mscratch");
119	  }
120	
121	  {  // L24: mepc/mcause/mtval/mie round-trip through the hybrid handoff, so the
122	     // hybrid policy compares each. mip is restored + re-read but EXCLUDED from
123	     // verify (its pending bits are hardware/platform-driven and diverge
124	     // between QEMU's functional clock and vsim's cycle-accurate one).
125	    hybrid_state_v1 ref = base_state();
