168	    const hybrid_state_v1 ref = base_state();
169	    hybrid_state_v1 got = ref;
170	    got.fpr[31] = 0;
171	    const DiffReport r = diff_states(ref, got);
172	    CHECK(r.diffs.size() == 1);
173	    CHECK(r.diffs[0].field == "f31");
174	  }
175	
