186	    const hybrid_state_v1 ref = base_state();
187	    hybrid_state_v1 got = ref;
188	    got.vl = 8;
189	    const DiffReport r = diff_states(ref, got);
190	    CHECK(r.diffs.size() == 1);
191	    CHECK(r.diffs[0].field == "vl");
192	  }
193	
