240	    CHECK(r.diffs.size() == 1);
241	    CHECK(r.diffs[0].field == "mcause");
242	    CHECK(r.diffs[0].got == 2);
243	  }
244	
245	  {  // mstatus stays EXCLUDED (dirty/impl-defined bits).
246	    hybrid_state_v1 ref = base_state();
247	    ref.flags = HYBRID_FLAG_RV64;
248	    hybrid_state_v1 got = ref;
249	    got.mstatus = 0x1;
250	    CHECK(diff_states(ref, got).ok());
251	  }
252	
253	  return andes_sim::test::report("state_diff");
254	}
