894	TEST_CASE("resume with HYBRID_FLAG_V: PB reload sweeps v0..v31 from scratch "
895	          "before the architectural V-CSR restore and counter restore")
896	{
897	  RecordingBus bus;
898	  bus.dmstatus_value = (1u << 9) | (1u << 17);
899	
900	  auto s = rv64_state(0x80001000, 0);
901	  s.flags  |= HYBRID_FLAG_V;
902	  s.vlenb  = 64;
903	  s.vl     = 16;
904	  s.vtype  = 0xC1;   // differs from the sweep's e8/m1 vtype (0xC0)
905	  s.vstart = 7;
906	
907	  // L26: the scratch GPA is the runtime top-of-mmap value (kScratch), passed
908	  // to the driver -- no longer a fixed constant. Assert the sweep stages it.
909	  hybrid::ResumeDriver driver(bus, kScratch);
910	  driver.resume(s);
911	
912	  // (a) every v0..v31 is reloaded via a vle8.v executed in the Program Buffer.
913	  std::vector<int> missing;
914	  std::optional<std::size_t> first_vle_idx, last_vle_idx;
915	  for (uint16_t v = 0; v < 32; ++v) {
916	    const uint32_t want = hybrid::encode_vle8_v(static_cast<uint8_t>(v), 7);
917	    std::optional<std::size_t> at;
918	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
919	      const auto& op = bus.ops[i];
920	      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
921	          && op.value == want) { at = i; break; }
922	    }
923	    if (!at) { missing.push_back(v); continue; }
924	    if (!first_vle_idx || *at < *first_vle_idx) first_vle_idx = at;
925	    if (!last_vle_idx  || *at > *last_vle_idx)  last_vle_idx  = at;
926	  }
927	  CHECK(missing.empty());
928	  REQUIRE(first_vle_idx.has_value());
929	  REQUIRE(last_vle_idx.has_value());
930	
931	  // (b) the per-register scratch GPA is staged in x7 (base pointer) for the
932	  //     first and last register.
933	  auto x7_gpa_staged = [&](uint64_t gpa) {
934	    for (std::size_t i = 2; i < bus.ops.size(); ++i) {
935	      const auto& op = bus.ops[i];
936	      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
937	          && (op.value & 0xFFFFu) == hybrid::regno_gpr(7)
938	          && ((op.value >> 16) & 1u)) {
939	        const auto& d0 = bus.ops[i - 2];
940	        const auto& d1 = bus.ops[i - 1];
941	        if (d0.reg == kData0 && d0.value == uint32_t(gpa & 0xFFFFFFFFu)
942	            && d1.reg == kData1 && d1.value == uint32_t(gpa >> 32))
943	          return true;
944	      }
945	    }
946	    return false;
947	  };
948	  CHECK(x7_gpa_staged(kScratch));
949	  CHECK(x7_gpa_staged(kScratch + 31ull * HYBRID_VLEN_BYTES_MAX));
950	
951	  // (c)/(d) the sweep runs before the architectural vstart restore (whose
952	  //     vsetvl would otherwise be clobbered) and before the mcycle restore
953	  //     (so the vle8.v insns cannot pollute the resumed counters).
954	  std::optional<std::size_t> vstart_cmd_idx, mcycle_cmd_idx;
955	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
956	    const auto& op = bus.ops[i];
957	    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
958	    const auto regno = static_cast<uint16_t>(op.value & 0xFFFFu);
959	    if (!vstart_cmd_idx && regno == hybrid::regno_csr(0x008)) vstart_cmd_idx = i;
960	    if (!mcycle_cmd_idx && regno == hybrid::regno_csr(0xB00)) mcycle_cmd_idx = i;
961	  }
962	  REQUIRE(vstart_cmd_idx.has_value());
963	  REQUIRE(mcycle_cmd_idx.has_value());
964	  CHECK(*last_vle_idx < *vstart_cmd_idx);
965	  CHECK(*last_vle_idx < *mcycle_cmd_idx);
966	}
