1091	TEST_CASE("B9: write_csr_abstract_or_pb busy-poll precedes cmderr inspection")
1092	{
1093	  // The B9 audit claimed write_csr_abstract_or_pb reads abstractcs without
1094	  // first polling busy. In fact write_64bit_register -> write_register_abstract
1095	  // calls poll_until_clear(busy) before returning, so by the time the cmderr
1096	  // check runs, busy is already clear. This test pins that contract: between
1097	  // every kCommand write and the next kAbstractcs read, the recorded ops
1098	  // must include at least one kAbstractcs read (the busy poll). If a future
1099	  // refactor regresses by removing the chained poll, this test fails.
1100	  RecordingBus bus;
1101	  bus.dmstatus_value = (1u << 9) | (1u << 17);
1102	
1103	  hybrid::ResumeDriver driver(bus, kScratch);
1104	  driver.resume(rv64_state(0x80001000, 0xdeadbeef));
1105	
1106	  // Walk ops; between each kCommand write and the very next kAbstractcs
1107	  // read by an unrelated caller, there must be at least one kAbstractcs
1108	  // read (the busy poll from write_register_abstract).
1109	  bool saw_cmd = false;
1110	  std::size_t reads_since_cmd = 0;
1111	  bool all_cmds_had_abstractcs_poll = true;
1112	  for (const auto& op : bus.ops) {
1113	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand) {
1114	      if (saw_cmd && reads_since_cmd == 0)
1115	        all_cmds_had_abstractcs_poll = false;
1116	      saw_cmd = true;
1117	      reads_since_cmd = 0;
1118	    } else if (saw_cmd && op.kind == DmiOp::Kind::Read
1119	               && op.reg == kAbstractcs) {
1120	      ++reads_since_cmd;
1121	    }
1122	  }
1123	  CHECK(all_cmds_had_abstractcs_poll);
1124	  // The final kCommand write must also be followed by an abstractcs read.
1125	  CHECK(reads_since_cmd > 0u);
