1179	  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);
1180	
1181	  s.priv = 4;  // out of the 2-bit prv field entirely
1182	  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);
1183	
1184	  // No abstract command may have been issued for a rejected state.
1185	  CHECK(count_writes_to(bus.ops, kCommand) == 0u);
1186	}
1187	
1188	TEST_CASE("L6/L2: S/U resume mirrors the producer's PMP block, addr before cfg")
1189	{
1190	  // With PMP implemented and no matching entry, every S/U access faults
1191	  // (priv spec v1.10) -- an S/U ROI cannot even fetch its first insn on the
1192	  // vsim side unless the producer's PMP block is mirrored in.
1193	  RecordingBus bus;
1194	  bus.dmstatus_value = (1u << 9) | (1u << 17);
1195	
1196	  auto s = rv64_state(0x80001000, 0);
1197	  s.priv = 0;  // U-mode
1198	  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) s.pmpaddr[i] = 0xb000 + i;
1199	  s.pmpcfg[0] = 0x1f;  // entry 0: NAPOT, RWX
1200	
1201	  hybrid::ResumeDriver driver(bus, kScratch);
1202	  driver.resume(s);
1203	
1204	  std::vector<uint16_t> regnos;
1205	  for (const auto& op : bus.ops)
1206	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
1207	        && ((op.value >> 16) & 1u) != 0u)
1208	      regnos.push_back(static_cast<uint16_t>(op.value & 0xffffu));
1209	
1210	  // All 64 pmpaddr CSRs (0x3B0..0x3EF) and the 8 even pmpcfg CSRs
1211	  // (0x3A0,0x3A2,..,0x3AE -- odd ones do not exist on RV64) are written.
1212	  std::size_t first_cfg = regnos.size(), last_addr = 0;
1213	  std::size_t n_addr = 0, n_cfg = 0, n_odd_cfg = 0;
1214	  for (std::size_t i = 0; i < regnos.size(); ++i) {
1215	    const auto r = regnos[i];
1216	    if (r >= 0x3B0 && r <= 0x3EF) { ++n_addr; last_addr = i; }
1217	    if (r >= 0x3A0 && r <= 0x3AF) {
1218	      if ((r & 1u) != 0u) ++n_odd_cfg;
1219	      else { ++n_cfg; if (i < first_cfg) first_cfg = i; }
1220	    }
1221	  }
1222	  CHECK(n_addr == 64u);
1223	  CHECK(n_cfg == 8u);
1224	  CHECK(n_odd_cfg == 0u);
1225	  // cfg activates the entries, so every addr write must precede every cfg
1226	  // write (a cfg-locked entry would discard the addr that follows it).
1227	  CHECK(last_addr < first_cfg);
1228	}
1229	
1230	TEST_CASE("L6: resume aborts loudly when the hart pins dcsr.prv (no S/U)")
1231	{
1232	  // An M-only core (e.g. NDS_NUM_PRIVILEGE_LEVELS=1 RTL) WARL-pins
1233	  // dcsr.prv to 3. Silently resuming would measure the ROI in the wrong
1234	  // privilege; the driver must verify its write took and throw instead.
1235	  RecordingBus bus;
1236	  bus.dmstatus_value = (1u << 9) | (1u << 17);
1237	  bus.regfile[hybrid::regno_csr(kCsrDcsr)] = 0x40000003ULL;  // reset: prv=M
1238	  bus.warl_ignore.insert(hybrid::regno_csr(kCsrDcsr));
1239	
1240	  auto s = rv64_state(0x80001000, 0);
1241	  s.priv = 1;
1242	
1243	  hybrid::ResumeDriver driver(bus, kScratch);
1244	  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);
1245	}
1246	
1247	TEST_CASE("L26: resume of V state with the scratch GPA unset throws (no silent "
1248	          "transport through a bogus address)")
1249	{
1250	  RecordingBus bus;
1251	  bus.dmstatus_value = (1u << 9) | (1u << 17);
1252	
1253	  auto s = rv64_state(0x80001000, 0);
1254	  s.flags |= HYBRID_FLAG_V;
1255	  s.vlenb = 16;
1256	
1257	  // Default ctor leaves scratch_gpa = kVScratchGpaUnset; a non-V resume would
1258	  // be fine, but a V resume must fail loudly rather than sweep from garbage.
1259	  hybrid::ResumeDriver driver(bus);
1260	  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);
1261	
1262	  // The same V state resumes cleanly once a real scratch GPA is supplied.
1263	  RecordingBus bus2;
1264	  bus2.dmstatus_value = (1u << 9) | (1u << 17);
1265	  hybrid::ResumeDriver ok(bus2, kScratch);
1266	  CHECK_NOTHROW(ok.resume(s));
1267	}
1268

