456	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: PB dumps v0..v31 to scratch "
457	          "after the architectural counter/CSR reads")
458	{
459	  RecordingBus bus;
460	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
461	
462	  hybrid_state_v1 input{};
463	  input.magic   = HYBRID_STATE_MAGIC;
464	  input.version = HYBRID_STATE_VERSION;
465	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
466	  input.priv    = 3;
467	  input.vlenb   = 64;
468	
469	  hybrid::StateDrain drain(bus, kScratch);
470	  (void) drain.drain_with_passthrough(input);
471	
472	  // (a) every v0..v31 is dumped via a vse8.v executed in the Program Buffer.
473	  std::vector<int> missing;
474	  std::optional<std::size_t> first_vse_idx;
475	  for (uint16_t v = 0; v < 32; ++v) {
476	    const uint32_t want = hybrid::encode_vse8_v(static_cast<uint8_t>(v), 7);
477	    std::optional<std::size_t> at;
478	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
479	      const auto& op = bus.ops[i];
480	      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
481	          && op.value == want) { at = i; break; }
482	    }
483	    if (!at) { missing.push_back(v); continue; }
484	    if (!first_vse_idx || *at < *first_vse_idx) first_vse_idx = at;
485	  }
486	  CHECK(missing.empty());
487	  REQUIRE(first_vse_idx.has_value());
488	
489	  // (b) the dump sweep runs AFTER the mcycle/minstret reads, so the sweep's
490	  //     vse8.v insns (and any counter increments) cannot corrupt the drained
491	  //     counters. minstret(0xB02) is the last counter read before the sweep.
492	  std::optional<std::size_t> minstret_read_idx;
493	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
494	    const auto& op = bus.ops[i];
495	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
496	    const auto regno   = static_cast<uint16_t>(op.value & 0xFFFFu);
497	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
498	    if (is_read && regno == hybrid::regno_csr(0xB02)) minstret_read_idx = i;
499	  }
500	  REQUIRE(minstret_read_idx.has_value());
501	  CHECK(*minstret_read_idx < *first_vse_idx);
502	}
