553	
554	  // Supplying a real scratch GPA lets the same V drain complete.
555	  RecordingBus bus2;
556	  bus2.dmstatus_value = kDmstatusHaltedAndAcked;
557	  hybrid::StateDrain ok(bus2, kScratch);
558	  CHECK_NOTHROW((void) ok.drain_with_passthrough(input));
559	}
560	
561	TEST_CASE("Andes v3: drain_with_passthrough re-reads the whole Andes CSR block "
562	          "from the hart, not the QEMU1 passthrough snapshot")
563	{
564	  RecordingBus bus;
565	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
566	  // Post-ROI values the measured region left in the hart's Andes CSRs.
567	  uint64_t hv = 0x700;
568	#define X(field, addr, name) bus.regfile[hybrid::regno_csr(addr)] = hv++;
569	  HYBRID_ANDES_CSR_LIST(X)
570	#undef X
571	  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
572	    bus.regfile[hybrid::regno_csr(0xBC0 + 2 * i)] = 0x800 + i;
573	  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
574	    bus.regfile[hybrid::regno_csr(0xBD0 + i)] = 0x900 + i;
575	
576	  hybrid_state_v1 input{};
577	  input.magic   = HYBRID_STATE_MAGIC;
578	  input.version = HYBRID_STATE_VERSION;
579	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES;
580	  input.priv    = 3;
581	  // Stale QEMU1 values; none must survive into the drained state.
582	#define X(field, addr, name) input.andes.field = 0xDEAD;
583	  HYBRID_ANDES_CSR_LIST(X)
584	#undef X
585	  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)  input.andes.pmacfg[i]  = 0xDEAD;
586	  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i) input.andes.pmaaddr[i] = 0xDEAD;
587	
588	  hybrid::StateDrain drain(bus, kScratch);
589	  const auto state = drain.drain_with_passthrough(input);
590	
591	  uint64_t exp = 0x700;
592	#define X(field, addr, name) CHECK(state.andes.field == exp++);
593	  HYBRID_ANDES_CSR_LIST(X)
594	#undef X
595	  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
596	    CHECK(state.andes.pmacfg[i] == uint64_t(0x800 + i));
597	  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
598	    CHECK(state.andes.pmaaddr[i] == uint64_t(0x900 + i));
599	}
