601	TEST_CASE("Andes v3: drain_with_passthrough without HYBRID_FLAG_ANDES leaves the "
602	          "Andes block as the passthrough snapshot (no re-read)")
603	{
604	  RecordingBus bus;
605	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
606	  bus.regfile[hybrid::regno_csr(0x7C4)]  = 0x1234;  // mxstatus live in the hart
607	  bus.regfile[hybrid::regno_csr(0xBD0)]  = 0x5678;  // pmaaddr0 live in the hart
