    csrw    0x7C9, a1                // mdcause
    li      a4, 0x0000000000000001   // select trigger 1 (premium has 2: 0,1)
    csrw    0x7A0, a4                // tselect
    li      a5, 0x0000000080001000   // trigger data 2 (match address; inert
    csrw    0x7A2, a5                //   without tdata1 enabling a match)
    li      a6, 0x0000000000000042   // mcontext value
    csrw    0x7A8, a6                // mcontext

    slti    x0, x0, 0x5A0            // ENTER ROI -> hand off to vsim

    csrr    a0, 0x7C9
    bne     a0, a1, regress          // mdcause restore lost? spin -> FAIL
    csrr    a0, 0x7A0
    bne     a0, a4, regress          // tselect
    csrr    a0, 0x7A2
    bne     a0, a5, regress          // tdata2
    csrr    a0, 0x7A8
    bne     a0, a6, regress          // mcontext

    slti    x0, x0, 0x5A1            // EXIT ROI -> vsim drains, exits 200

    li      t0, 0xe0080000
    sw      x0, 0(t0)
1:  j       1b

regress:
    j       regress                  // a restored CSR is wrong: hang -> FAIL

