41	std::string plan_step_rc_error(size_t step, const Step& s, int expect_rc,
42	                               int got_rc) {
43	  std::string m = "plan step " + std::to_string(step) + ": expected exit " +
44	                  std::to_string(expect_rc) + ", got " + std::to_string(got_rc);
45	  // A drain step (expect_rc is the handoff/drain code) that exits 0 ran the ELF
46	  // to completion without ever hitting its ROI boundary -- the marker/pc
47	  // trigger never fired. This is THE common "unmarked ELF / wrong trigger"
48	  // mistake; name the kind so the fix is obvious, not a bare exit code.
49	  if (got_rc == 0 && expect_rc == kDrainRc)
50	    m += " -- the " + s.role + " ran to completion without reaching its " +
51	         s.trigger.kind +
52	         " trigger boundary (the ROI never drained; check the ELF actually "
53	         "reaches the " +
54	         s.trigger.kind + ")";
55	  return m;
56	}
57	
58	LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
59	                                std::string& err) {
60	  err.clear();
61	  LegTriggerArgs out;
62	  if (t.kind == "marker") return out;  // markers detected by plugin/vsim, not argv
63	
64	  const bool fast = role == "fast-leg";
65	  const bool accurate = role == "accurate-leg";
66	  if (!fast && !accurate) return out;  // other roles carry no trigger args
67	
68	  // Required-param lookup. A missing key is a caller bug; surface it (don't
69	  // throw) so plan_argvs can report which step failed.
70	  auto param = [&](const char* key) -> const std::string* {
71	    auto it = t.params.find(key);
72	    if (it == t.params.end()) {
73	      err = "trigger '" + t.kind + "' missing param '" + key + "'";
74	      return nullptr;
75	    }
76	    return &it->second;
77	  };
78	
79	  if (t.kind == "pc") {
80	    if (fast) {
81	      if (const std::string* p = param("enter_pc"))
82	        out.plugin_suffix = ",enter_pc=" + *p;
83	    } else if (const std::string* p = param("exit_pc")) {
84	      out.extra = {"--hybrid-exit-pc", *p};
85	    }
86	    return out;
87	  }
88	
89	  // verify oracle leg (verify_oracle F4): a pure-QEMU drain at the ROI exit
90	  // boundary, sampling at vsim's actual halt pc (drain_pc -- the DMI halt
91	  // lands a few insns past the trigger, and the comparison is only valid at
92	  // the same architectural point). qemu-only: the oracle plan has no
93	  // accurate leg.
94	  if (t.kind == "verify-marker" || t.kind == "verify-pc") {
95	    if (!fast) return out;
96	    std::string suffix = ",exit_marker=1";
97	    if (t.kind == "verify-pc") {
98	      const std::string* p = param("exit_pc");
99	      if (!p) return out;
100	      suffix = ",exit_pc=" + *p;
101	    }
102	    if (const std::string* p = param("drain_pc"))
103	      out.plugin_suffix = suffix + ",drain_pc=" + *p;
104	    return out;
105	  }
106	
107	  err = "unknown trigger kind '" + t.kind + "'";
108	  return out;
109	}
110	
111	std::vector<std::vector<std::string>> plan_argvs(
112	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
113	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
114	  std::vector<std::vector<std::string>> out;
115	  out.reserve(plan.steps.size());
116	  std::string prev_state_out;  // empty for the cold first leg
117	
118	  // hw-config sync: {vlen} comes from the accurate-leg engine's descriptor.
119	  long vlen = 0;
120	  for (const Step& s : plan.steps)
121	    if (s.role == "accurate-leg")
122	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id))
123	        if (e->vlen > 0) vlen = e->vlen;
124	  const std::string vlen_str = std::to_string(synced_vlen(vlen));
125	
126	  for (size_t i = 0; i < plan.steps.size(); ++i) {
127	    const Step& step = plan.steps[i];
128	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
129	    if (!eng) {
130	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
131	            step.engine_id + "'";
132	      return {};
133	    }
134	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
135	    if (!tmpl) {
136	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
137	            "' has no invoke template for role '" + step.role + "'";
138	      return {};
139	    }
140	
141	    std::string trig_err;
142	    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
143	    if (!trig_err.empty()) {
144	      err = "plan step " + std::to_string(i) + ": " + trig_err;
145	      return {};
146	    }
147	
148	    const std::string state_out = state_path(workdir, i);
149	    const std::map<std::string, std::string> m = {
150	        {"bin", eng->bin_path},
151	        {"elf", plan.elf},
152	        {"plugin", ctx.plugin_path},
153	        {"mmap", ctx.mmap_path},
154	        {"mmap_size", std::to_string(ctx.mem_size)},
155	        {"mmap_base", ctx.mmap_base},
156	        {"state_in", prev_state_out},
157	        {"state_out", state_out},
158	        {"trigger", lt.plugin_suffix},  // qemu plugin comma-suffix (empty for marker)
159	        {"vlen", vlen_str},
160	    };
161	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
162	    if (!err.empty()) {
163	      err = "plan step " + std::to_string(i) + ": " + err;
164	      return {};
165	    }
166	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
167	    // after the filled template (matches tests/e2e.sh's ordering).
168	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
169	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
170	    out.push_back(std::move(argv));
171	    prev_state_out = state_out;
172	  }
173	  err.clear();
174	  return out;
175	}
176	
177	PlanResult run_plan(const Plan& plan,
178	                    const std::vector<EngineDescriptor>& engines,
179	                    const PlanOptions& opts) {
180	  PlanResult res;
181	  if (plan.steps.empty()) {
182	    res.error = "plan has no steps";
183	    return res;
184	  }
185	
186	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
187	  std::string mmap_path = plan.mmap_path;
188	  const bool own_mmap = mmap_path.empty();
189	  if (own_mmap) {
190	    std::string err;
191	    // L26/F2: back the mmap with one V-scratch page above the program's RAM.
192	    mmap_path = allocate(physical_mmap_bytes(plan.mem_size), err);
193	    if (mmap_path.empty()) {
194	      res.error = err;
195	      return res;
196	    }
197	  }
198	
199	  // A private dir for the threaded drain files.
200	  std::error_code ec;
201	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
202	  std::string tmpl = workdir.string();
203	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
204	  tbuf.push_back('\0');
205	  const char* made = ::mkdtemp(tbuf.data());
206	  if (!made) {
207	    if (own_mmap) ::unlink(mmap_path.c_str());
208	    res.error = "failed to create plan work dir";
209	    return res;
210	  }
211	  const std::string wd = made;
212	
213	  RuntimeCtx ctx;
214	  ctx.mmap_path = mmap_path;
215	  // L26/F2: the legs (QEMU backend size, vsim --shared-mem-size) see the
216	  // PHYSICAL window -- program RAM plus the V-scratch page. The program's own
217	  // linker script still uses only --mem-size, so the scratch page sits above
218	  // everything it can address.
219	  ctx.mem_size = physical_mmap_bytes(plan.mem_size);
220	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
221	
222	  std::string err;
223	  const std::vector<std::vector<std::string>> argvs =
224	      plan_argvs(plan, engines, wd, ctx, err);
225	  if (!err.empty()) {
226	    res.error = err;
227	  } else {
228	    for (size_t i = 0; i < argvs.size(); ++i) {
229	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
230	      if (r.spawn_failed) {
231	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
232	        break;
233	      }
234	      if (r.timed_out) {
235	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
236	                    std::to_string(opts.timeout_ms) + " ms";
237	        break;
238	      }
239	      if (r.rc != opts.expect_rc) {
240	        res.error = plan_step_rc_error(i, plan.steps[i], opts.expect_rc, r.rc);
241	        break;
242	      }
243	      const StateFile sf = read_state_file(state_path(wd, i));
244	      if (!sf.ok()) {
245	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
246	        break;
247	      }
248	      res.phases.push_back({sf.st.mcycle, sf.st.minstret, r.out, sf.st});
249	    }
250	  }
251	
252	  fs::remove_all(wd, ec);
253	  if (own_mmap) ::unlink(mmap_path.c_str());
254	  return res;
255	}
