1	// Unit tests for the F6 phase-plan executor's pure core:
2	//   - build_argv  (driver/argv.hpp)     invoke-template placeholder fill
3	//   - plan_argvs  (driver/run_plan.hpp) state-file threading across steps
4	//
5	// These cover everything in run_plan EXCEPT the live spawn loop, which the
6	// integration acceptance (tests/andes_sim/test_andes_sim_f6.sh -> a real
7	// 2-step qemu+vsim run) exercises. Plain assert-and-count harness; run by that
8	// same f6 script. No QEMU2 leg exists -- handback was removed.
9	#include <map>
10	#include <string>
11	#include <vector>
12	
13	#include "argv.hpp"
14	#include "engine_descriptor.hpp"
15	#include "plan.hpp"
16	#include "run_plan.hpp"
17	#include "test_check.hpp"
18	
19	using namespace andes_sim;
20	using andes_sim::test::check_eq;
21	
22	namespace {
23	
24	// The canonical drain templates (what builtin_qemu() and vsim --describe ship).
25	const std::vector<std::string> kQemuFastLeg = {
26	    "{bin}",
27	    "-object", "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
28	    "-machine", "andes_ae350,memory-backend=mem",
29	    "-cpu", "andes-ax45mpv,vlen={vlen}",
30	    "-nographic",
31	    "-semihosting-config", "enable=on,target=native",
32	    "-bios", "{elf}",
33	    "-plugin", "{plugin},outfile={state_out}{trigger}",
34	};
35	
36	const std::vector<std::string> kVsimAccurateLeg = {
37	    "{bin}", "{elf}",
38	    "--resume-from-qemu", "{state_in}",
39	    "--handoff-out", "{state_out}",
40	    "--shared-mem-path", "{mmap}",
41	    "--shared-mem-size", "{mmap_size}",
42	    "--shared-mem-base", "{mmap_base}",
43	};
44	
45	EngineDescriptor fake(const std::string& id, const std::string& bin,
46	                      const std::string& role,
47	                      const std::vector<std::string>& tmpl) {
48	  EngineDescriptor d;
49	  d.id = id;
50	  d.bin_path = bin;
51	  d.invoke.push_back({role, tmpl});
52	  return d;
53	}
54	
55	}  // namespace
56	
57	int main() {
58	  // --- build_argv: every placeholder filled, including substring + repeat ---
59	  {
60	    std::string err;
61	    std::map<std::string, std::string> ctx = {
62	        {"bin", "/q"},      {"elf", "/e"},     {"plugin", "/p"},
63	        {"mmap", "/m"},     {"mmap_size", "134217728"}, {"state_out", "/s0"},
64	        {"trigger", ""},  // marker: no plugin suffix
65	        {"vlen", "512"},
66	    };
67	    std::vector<std::string> got = build_argv(kQemuFastLeg, ctx, err);
68	    CHECK(err.empty());
69	    check_eq(got,
70	             {"/q", "-object",
71	              "memory-backend-file,id=mem,share=on,mem-path=/m,size=134217728",
72	              "-machine", "andes_ae350,memory-backend=mem", "-cpu",
73	              "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
74	              "enable=on,target=native", "-bios", "/e", "-plugin",
75	              "/p,outfile=/s0"},
76	             "qemu");
77	  }
78	  {
79	    std::string err;
80	    std::map<std::string, std::string> ctx = {
81	        {"bin", "/v"},  {"elf", "/e"},  {"state_in", "/s0"},
82	        {"state_out", "/s1"}, {"mmap", "/m"}, {"mmap_size", "134217728"},
83	        {"mmap_base", "0x0"},
84	    };
85	    std::vector<std::string> got = build_argv(kVsimAccurateLeg, ctx, err);
86	    CHECK(err.empty());
87	    check_eq(got,
88	             {"/v", "/e", "--resume-from-qemu", "/s0", "--handoff-out", "/s1",
89	              "--shared-mem-path", "/m", "--shared-mem-size", "134217728",
90	              "--shared-mem-base", "0x0"},
91	             "vsim");
92	  }
93	  // a repeated placeholder expands every occurrence
94	  {
95	    std::string err;
96	    std::vector<std::string> got =
97	        build_argv({"a={x},b={y},a2={x}"}, {{"x", "1"}, {"y", "2"}}, err);
98	    CHECK(err.empty());
99	    check_eq(got, {"a=1,b=2,a2=1"}, "repeat");
100	  }
101	  // an unknown placeholder is an error, not a silent empty fill
102	  {
103	    std::string err;
104	    std::vector<std::string> got = build_argv({"{bogus}"}, {{"x", "1"}}, err);
105	    CHECK(got.empty());
106	    CHECK(!err.empty());
107	  }
108	
109	  // --- plan_argvs: thread state files across a 2-step hybrid plan ---
110	  std::vector<EngineDescriptor> engines = {
111	      fake("qemu", "/qbin", "fast-leg", kQemuFastLeg),
112	      fake("vsim:test", "/vbin", "accurate-leg", kVsimAccurateLeg),
113	  };
