#ifndef OPTPARSE_HPP
#define OPTPARSE_HPP

#include <cstdint>

#include <charconv>
#include <concepts>
#include <functional>
#include <optional>
#include <span>
#include <stdexcept>
#include <string>
#include <string_view>
#include <unordered_map>
#include <vector>

template<std::integral T>
[[nodiscard]]
auto to_int(const std::string_view s) -> std::optional<T>
{
  const auto ok = std::from_chars_result{.ptr = s.end(), .ec = std::errc{}};
  if (auto value = T{}; std::from_chars(s.begin(), s.end(), value) == ok)
    return value;
  return std::nullopt;
}

struct reset_vector_spec
{
  std::optional<size_t> hart; // nullopt = all harts
  uint64_t addr;
};

// Parse "<addr>" or "<hart>:<addr>", where addr supports 0x prefix
[[nodiscard]]
inline auto parse_reset_vector(const std::string_view s) -> reset_vector_spec
{
  auto str = std::string{s};
  try {
    auto colon = str.find(':');
    if (colon == std::string::npos)
      return {std::nullopt, std::stoull(str, nullptr, 0)};
    auto hart = std::stoull(str.substr(0, colon), nullptr, 0);
    auto addr = std::stoull(str.substr(colon + 1), nullptr, 0);
    return {hart, addr};
  } catch (...) {
    throw std::runtime_error("invalid --reset-vector: " + str
                             + " (expected <addr> or <hart>:<addr>)");
  }
}

class parser
{
public:
  using string_handler = std::function<void(std::string_view)>;
  using flag_handler = std::function<void()>;

  struct handler
  {
    bool takes_value = false;
    string_handler value_fn{};
    flag_handler flag_fn{};
  };

  std::unordered_map<std::string_view, handler> longopts;
  std::unordered_map<char, handler> shortopts;

  string_handler posarg_handler = [](auto) {};
  string_handler unknown_handler = [](const std::string_view s) {
    throw std::runtime_error{"Unrecognized option: " + std::string{s}};
  };

  auto longopt(const std::string_view k, const string_handler& h) -> parser&
  {
    longopts.emplace(k, handler{.takes_value = true, .value_fn = h});
    return *this;
  }

  auto longflag(const std::string_view k, const flag_handler& h) -> parser&
  {
    longopts.emplace(k, handler{.takes_value = false, .flag_fn = h});
    return *this;
  }

  auto shortopt(const char c, const string_handler& h) -> parser&
  {
    shortopts.emplace(c, handler{.takes_value = true, .value_fn = h});
    return *this;
  }

  auto shortflag(const char c, const flag_handler& h) -> parser&
  {
    shortopts.emplace(c, handler{.takes_value = false, .flag_fn = h});
    return *this;
  }

  auto posarg(const string_handler& h) -> parser&
  {
    posarg_handler = h;
    return *this;
  }

  auto unknown(const string_handler& h) -> parser&
  {
    unknown_handler = h;
    return *this;
  }

  void parse(const std::span<const std::string_view> args) const
  {
    if (args.empty())
      return;

    for (auto it = args.begin() + 1; it != args.end(); ++it) {
      const auto s = *it;

      if (s == "--") {
        for (it = std::next(it); it != args.end(); ++it)
          posarg_handler(*it);
        break;
      } else if (s.starts_with("--")) {
        const auto eq = s.find('=', 2);
        const auto key =
          eq == std::string::npos ? s.substr(2, eq) : s.substr(2, eq - 2);

        const auto hit = longopts.find(key);
        if (hit == std::end(longopts)) {
          unknown_handler(s.substr(0, eq));
          continue;
        }

        const auto& opt = hit->second;
        if (!opt.takes_value) {
          opt.flag_fn();
        } else if (eq != std::string::npos) { // --key=value
          opt.value_fn(s.substr(eq + 1));
        } else if (++it != args.end()) { // --key value
          opt.value_fn(*it);
        } else {
          throw std::runtime_error{"No value given for --" + std::string{key}};
        }
      } else if (s.starts_with("-")) {
        for (auto cit = s.begin() + 1; cit != s.end(); ++cit) {
          const char c = *cit;
          const auto hit = shortopts.find(c);

          if (hit == std::end(shortopts)) {
            unknown_handler(std::string("-") + c);
            continue;
          }

          const auto& opt = hit->second;
          if (!opt.takes_value) {
            opt.flag_fn();
          } else if (const auto value = std::next(cit); value != s.end()) {
            opt.value_fn(s.substr(value - s.begin()));
            cit = std::prev(s.end());
          } else if (++it != args.end()) { // -o value
            opt.value_fn(*it);
          } else {
            throw std::runtime_error{"No value given for -" + std::string{c}};
          }
        }
      } else {
        posarg_handler(s);
      }
    }
  }
};

#endif

// Subprocess helpers for andesim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDESIM_PROCESS_HPP
#define ANDESIM_PROCESS_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// and stderr are redirected to /dev/null. If the child runs longer than
// timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms);

// Run argv to completion with the child INHERITING this process's stdout and
// stderr (its output streams straight to the terminal) and stdin from
// /dev/null; chdir to `cwd` first if non-empty. No capture, no timeout. Returns
// the child's exit code, 128+signal if it was signalled, or -1 on spawn
// failure. Used by `build` to delegate to setup.sh / build_*.sh / make.
int run_inherit(const std::vector<std::string>& argv, const std::string& cwd);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --mode fast|cycle`: the engine reads/writes the terminal directly,
// so an interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

// Fork a child that execs argv with inherited stdio and return immediately
// without waiting. Used by `run --mode cycle --gdb` to launch vsim in the
// background before exec-ing ICEman in the foreground. Returns the child pid
// on success, -1 on empty argv or fork failure.
int fork_background(const std::vector<std::string>& argv);

}  // namespace andes_sim

#endif  // ANDESIM_PROCESS_HPP

