4	// docs/engine_interface.md. The framework keeps zero per-engine code; every
5	// capability it needs comes from here.
6	#ifndef ANDESIM_ENGINE_DESCRIPTOR_HPP
7	#define ANDESIM_ENGINE_DESCRIPTOR_HPP
8	
9	#include <string>
10	#include <string_view>
11	#include <vector>
12	
13	#include "json.hpp"
14	
15	namespace andes_sim {
16	
17	// One role's argv template, e.g. role "accurate-leg" -> {"{bin}",
18	// "--resume-from-qemu", "{state_in}", ...}. {placeholders} are filled by the
19	// plan executor (F6).
20	struct EngineInvoke {
21	  std::string role;
22	  std::vector<std::string> argv;
23	};
24	
25	struct EngineDescriptor {
26	  std::string id;                       // "qemu", "verilator:ax45mpv_premium"
27	  std::string type;                     // qemu | verilator | alioth | sid
28	  std::string kind;                     // functional | cycle-accurate
29	  long vlen = 0;                        // RVV params; 0 = not reported
30	  long dlen = 0;
31	  long elen = 0;
32	  long xlen = 0;
33	  std::vector<std::string> triggers;    // marker | pc
34	  std::vector<std::string> roles;       // standalone | fast-leg | accurate-leg
35	  std::vector<std::string> state;       // resume | drain (hybrid_state_v1 caps)
36	  std::vector<std::string> andes_csrs;  // Andes CSRs this engine implements; the
37	                                        // --verify gate (empty = compare all)
38	  std::vector<EngineInvoke> invoke;     // argv template per role
39	  std::string result;                   // stderr:<re> | state.mcycle
40	
41	  // Filled by the registry, not present in the JSON:
42	  std::string bin_path;                 // resolved path to the binary
43	  std::string source;                   // built-in | --describe | sidecar
44	
45	  const std::vector<std::string>* invoke_for(std::string_view role) const {
46	    for (const EngineInvoke& iv : invoke)
47	      if (iv.role == role) return &iv.argv;
48	    return nullptr;
49	  }
50	};
51	
52	// Build a descriptor from parsed JSON. Returns "" on success or an error
53	// message naming the first problem (id and type are required).
54	inline std::string descriptor_from_json(const json::Value& v,
55	                                        EngineDescriptor& out) {
56	  if (!v.is_object()) return "descriptor is not a JSON object";
57	
58	  const json::Value* id = v.find("id");
59	  if (!id || !id->is_string() || id->str.empty()) return "missing string 'id'";
60	  out.id = id->as_string();
61	
62	  const json::Value* type = v.find("type");
63	  if (!type || !type->is_string()) return "missing string 'type'";
64	  out.type = type->as_string();
65	
66	  if (const json::Value* x = v.find("kind")) out.kind = x->as_string();
67	  if (const json::Value* x = v.find("vlen")) out.vlen = x->as_int();
68	  if (const json::Value* x = v.find("dlen")) out.dlen = x->as_int();
69	  if (const json::Value* x = v.find("elen")) out.elen = x->as_int();
70	  if (const json::Value* x = v.find("xlen")) out.xlen = x->as_int();
71	  if (const json::Value* x = v.find("triggers")) out.triggers = x->as_string_array();
72	  if (const json::Value* x = v.find("roles")) out.roles = x->as_string_array();
73	  if (const json::Value* x = v.find("state")) out.state = x->as_string_array();
74	  if (const json::Value* x = v.find("andes_csrs"))
75	    out.andes_csrs = x->as_string_array();
76	  if (const json::Value* x = v.find("result")) out.result = x->as_string();
77	
78	  if (const json::Value* inv = v.find("invoke"); inv && inv->is_object()) {
79	    for (size_t k = 0; k < inv->keys.size(); ++k)
80	      out.invoke.push_back({inv->keys[k], inv->vals[k].as_string_array()});
81	  }
82	  return "";
83	}
84	
85	}  // namespace andes_sim
86	
87	#endif  // ANDESIM_ENGINE_DESCRIPTOR_HPP
